mapper.select:
SELECT EXISTS (
  SELECT 1
  FROM profiles
  WHERE profile_id = #{profileId}
    AND is_deleted = false
)

SELECT EXISTS (
  SELECT 1
  FROM profiles
  WHERE username = #{username}
    AND is_deleted = false
)

SELECT EXISTS (
  SELECT 1
  FROM profiles
  WHERE phone_number = #{phoneNumber}
    AND is_deleted = false
)

SELECT EXISTS (
  SELECT 1
  FROM profiles
  WHERE email = #{email}
    AND is_deleted = false
)

SELECT EXISTS (
  SELECT 1
  FROM profiles
  WHERE phone_number = #{phoneNumber}
    AND profile_id != #{profileId}
    AND is_deleted = false
)
